/**
 * Request body for `POST /api/admin/bus-layouts` (create) and
 * `PUT /api/admin/bus-layouts/{id}` (update — metadata patch only;
 * the seat grid can never be regenerated on an existing layout
 * without orphaning per-trip seat inventory).
 */
export type UpsertBusLayoutRequest = {
    brandId?: string | null;
    /**
     * Optional layout JSON blob (reserved for seat-map geometry).
     */
    layoutData?: string | null;
    name?: string | null;
    plan?: null | SeatPlan;
    seatGrid?: null | SeatGridSpec;
    /**
     * Total bookable seats. When `seat_grid` is provided the computed
     * `rows × cols × floors` wins; otherwise this value is stored.
     */
    totalSeats?: number | null;
    /**
     * Legacy vehicle-class code (`limousine`, `sleeper`, …) — kept in
     * sync with the `vehicle_type` catalog codes.
     */
    vehicleType?: string | null;
};

/**
 * Request body for `POST /api/admin/pickup-points` + `PUT /api/admin/pickup-points/{id}`.
 */
export type UpsertPickupPointRequest = {
    address?: string | null;
    kind?: string | null;
    lat?: number | null;
    lon?: number | null;
    name?: string | null;
    routeId?: string | null;
    stopOrder?: number | null;
};

/**
 * Request body for `POST /api/admin/routes` + `PUT /api/admin/routes/{id}`.
 */
export type UpsertRouteRequest = {
    brandId?: string | null;
    endLocationId?: string | null;
    name?: string | null;
    /**
     * City slug (e.g. `"ha-noi"`). Max 20 chars — matches the DB
     * column `VARCHAR(20) NOT NULL`. The slug MUST be one of the
     * values in `crate::cities::CITIES`; we don't enforce that here
     * (validator doesn't have access to the static list) but the
     * frontend dropdown only sends known slugs. Required — a route
     * without start/end cities is meaningless.
     */
    startLocationId?: string | null;
    status?: string | null;
};

/**
 * One entry of the ordered `points` array on schedule create/update.
 * The array position defines `stopOrder`; `kind` is derived
 * (first = `pickup`, last = `drop`, else `middle`).
 */
export type UpsertSchedulePointItem = {
    addressId?: string | null;
    /**
     * Optional `HH:MM` arrival time at this stop. Validated in the
     * service (00:00–23:59); `null`/omitted clears it.
     */
    arrivalTime?: string | null;
};

/**
 * Request body for `POST /api/admin/schedules` + `PUT /api/admin/schedules/{id}`.
 */
export type UpsertScheduleRequest = {
    amenities?: string | null;
    basePriceAdult?: number | null;
    /**
     * Child price of a standard seat; `0` = the brand's discount applies.
     */
    basePriceChild?: number | null;
    /**
     * Bus layout id (string on the wire, `Uuid` in Rust).
     */
    busLayoutId?: string | null;
    /**
     * When present, replaces the fares of every non-standard seat class.
     */
    classFares?: Array<SeatClassFare> | null;
    daysOfWeek?: string | null;
    departureTime?: string | null;
    effectiveFrom?: string | null;
    effectiveTo?: string | null;
    /**
     * When present, replaces the schedule's whole point sequence.
     * Requires ≥ 2 items (departure + destination); `kind` and
     * `stopOrder` are derived from the array position.
     */
    points?: Array<UpsertSchedulePointItem> | null;
    routeId?: string | null;
    /**
     * Vehicle class from the admin-managed `vehicle_type` catalog.
     * Validated in the service (404-style validation error when unknown).
     */
    vehicleTypeId?: string | null;
};

/**
 * Body of `PUT /api/admin/bus-layouts/{id}/plan`.
 */
export type UpsertSeatPlanRequest = {
    plan: SeatPlan;
};

/**
 * Request body for `POST /api/admin/vehicle-types` +
 * `PUT /api/admin/vehicle-types/{id}`. All fields optional on update
 * (patch semantics); `code`+`label` required on create.
 */
export type UpsertVehicleTypeRequest = {
    /**
     * Required on create, immutable-style identity (must stay a slug).
     */
    code?: string | null;
    description?: string | null;
    label?: string | null;
    sortOrder?: number | null;
    /**
     * `active` | `disabled` (defaults to `active` on create).
     */
    status?: string | null;
    totalSeats?: number | null;
};

/**
 * Response of `GET /api/users` — one page + the filtered total (server-
 * side pagination for the admin Users table).
 */
export type UserListResponse = {
    items: Array<UserOut>;
    total: number;
};

export type UserOut = {
    createdAt: string;
    /**
     * User's email. The underlying column is non-null but may be empty —
     * we normalise to `None` for the wire so the frontend's optional type
     * is honest.
     */
    email?: string | null;
    fullName: string;
    id: string;
    /**
     * True for the NullClaw bot account (role management is refused).
     */
    isBot: boolean;
    /**
     * `"user"` | `"employee"` | `"admin"` (three-role model).
     */
    role: string;
    /**
     * Account status (`active` / `blocked`).
     */
    status: string;
};

/**
 * `POST /api/admin/system/database/vacuum` result.
 */
export type VacuumResponse = {
    /**
     * File size after the VACUUM + a WAL checkpoint (db + wal).
     */
    afterBytes: number;
    /**
     * File size before the VACUUM (db + wal).
     */
    beforeBytes: number;
    /**
     * `before - after` (can legitimately be small: WAL + freelist were
     * already bounded).
     */
    reclaimedBytes: number;
    /**
     * Wall time of the VACUUM (s) — expect roughly one full-DB
     * read + write; plan the maintenance window around it.
     */
    seconds: number;
};

export type VitalsReport = {
    connection?: string;
    delta: number;
    deviceMemory?: number;
    id: string;
    name: string;
    navigationType: string;
    path?: string;
    rating: string;
    timestamp?: number;
    userAgent?: string;
    value: number;
};

export type WebsocketStats = {
    /**
     * Total live WS connections (across all users + employees).
     */
    connections: number;
    /**
     * Distinct client IPs (used for per-IP connection caps).
     */
    distinctIps: number;
    /**
     * Idempotency cache entries (pending `clientMsgId` lookups).
     */
    idempotencyEntries: number;
    /**
     * Configured max connections (from `WS_MAX_CONNECTIONS`).
     */
    maxConnections: number;
    /**
     * Number of distinct brands with online employees. The hub
     * indexes online employees by brand key (`brandId → employeeId →
     * set<socketId>`). This is the count of brand keys with ≥1
     * online employee.
     */
    onlineEmployeeBrands: number;
    /**
     * Total online employees (sum across all brands). Useful for
     * the admin dashboard — "how many support staff are online?".
     */
    onlineEmployees: number;
    /**
     * Live hardware-bounded admission telemetry — the RAM/fd numbers
     * that ACTUALLY cap connections now that the static caps default
     * to unlimited (see `middleware::resource_guard`).
     */
    resources: ResourceGuardStats;
    /**
     * Number of chat rooms (one per open channel that has at least
     * one joined socket). Empty rooms are cleaned up by the hub GC.
     */
    rooms: number;
};

